"""Preserve metadata with recorded GPU bytes, including FIFO switches and display lists."""
from pathlib import Path
import json,sys
root=Path(sys.argv[1])
ops=json.loads("{\"f\": [[\"uint32_t g_gp_len;\", \"uint32_t g_gp_len;\\nuint8_t g_cpu_write_tag;\\nuint8_t g_gp_tags[64];\\nstatic uint8_t g_ram_draw_tags[0x4000000];\"], [\"static uint32_t g_pending_need;\", \"static uint32_t g_pending_need;\\nstatic std::vector<uint8_t> g_pending_tags;\"], [\"void gx::set_draw_tag(uint8_t tag) {\\n    if (!fe_threaded()) {\\n        draw_tag_reached(tag);\\n        return;\\n    }\\n    fe_submit();\\n    PendingTurn t;\\n    memset(t.q, 0, sizeof(t.q));\\n    t.tag = tag;\\n    std::lock_guard<std::mutex> lk(g_fe_mutex);\\n    t.at = g_fe_handed;\\n    g_turns.push_back(t);\\n}\\n\", \"void gx::set_draw_tag(uint8_t tag) { g_cpu_write_tag=tag; }\"], [\"    memcpy(phys_ptr(addr), g_gp_buf, fit);\", \"    memcpy(phys_ptr(addr), g_gp_buf, fit);\\n    memcpy(g_ram_draw_tags+addr,g_gp_tags,fit);\"], [\"    if (g_gp_len > 32) memmove(g_gp_buf, g_gp_buf + 32, g_gp_len - 32);\", \"    if (g_gp_len > 32) {memmove(g_gp_buf,g_gp_buf+32,g_gp_len-32);memmove(g_gp_tags,g_gp_tags+32,g_gp_len-32);}\"], [\"    memcpy(phys_ptr(addr), g_gp_buf, dma_fit(\\\"write-gather\\\", addr, g_gp_len));\", \"    memcpy(phys_ptr(addr), g_gp_buf, dma_fit(\\\"write-gather\\\", addr, g_gp_len));\\n    memcpy(g_ram_draw_tags+addr,g_gp_tags,g_gp_len);\"], [\"void gp_write8(uint8_t v) {\\n    g_gp_buf[g_gp_len++] = v;\\n    if (g_gp_len >= 32) gp_flush32();\\n}\\n\", \"void gp_write8(uint8_t v) {\\n    g_gp_tags[g_gp_len]=g_cpu_write_tag;\\n    g_gp_buf[g_gp_len++] = v;\\n    if (g_gp_len >= 32) gp_flush32();\\n}\\n\"], [\"void gp_write16(uint16_t v) {\\n    g_gp_buf[g_gp_len++] = v >> 8;\\n    g_gp_buf[g_gp_len++] = (uint8_t)v;\\n    if (g_gp_len >= 32) gp_flush32();\\n}\\n\", \"void gp_write16(uint16_t v) {\\n    g_gp_tags[g_gp_len]=g_cpu_write_tag;\\n    g_gp_buf[g_gp_len++] = v >> 8;\\n    g_gp_tags[g_gp_len]=g_cpu_write_tag;\\n    g_gp_buf[g_gp_len++] = (uint8_t)v;\\n    if (g_gp_len >= 32) gp_flush32();\\n}\\n\"], [\"void gp_write32(uint32_t v) {\\n#ifdef GCN_CALL_TRACE\\n    gp_stack_probe(v);\\n#endif\\n    g_gp_buf[g_gp_len++] = v >> 24;\\n    g_gp_buf[g_gp_len++] = (uint8_t)(v >> 16);\\n    g_gp_buf[g_gp_len++] = (uint8_t)(v >> 8);\\n    g_gp_buf[g_gp_len++] = (uint8_t)v;\\n    if (g_gp_len >= 32) gp_flush32();\\n}\\n\", \"void gp_write32(uint32_t v) {\\n#ifdef GCN_CALL_TRACE\\n    gp_stack_probe(v);\\n#endif\\n    g_gp_tags[g_gp_len]=g_cpu_write_tag;\\n    g_gp_buf[g_gp_len++] = v >> 24;\\n    g_gp_tags[g_gp_len]=g_cpu_write_tag;\\n    g_gp_buf[g_gp_len++] = (uint8_t)(v >> 16);\\n    g_gp_tags[g_gp_len]=g_cpu_write_tag;\\n    g_gp_buf[g_gp_len++] = (uint8_t)(v >> 8);\\n    g_gp_tags[g_gp_len]=g_cpu_write_tag;\\n    g_gp_buf[g_gp_len++] = (uint8_t)v;\\n    if (g_gp_len >= 32) gp_flush32();\\n}\\n\"], [\"            g_pending.assign(data + used, data + len);\", \"            g_pending.assign(data + used, data + len);\\n            const auto offset=uintptr_t(data)-uintptr_t(g_mem);\\n            g_pending_tags.assign(g_ram_draw_tags+offset+used,g_ram_draw_tags+offset+len);\"], [\"    g_pending.insert(g_pending.end(), data, data + len);\", \"    g_pending.insert(g_pending.end(), data, data + len);\\n    const auto offset=uintptr_t(data)-uintptr_t(g_mem);\\n    g_pending_tags.insert(g_pending_tags.end(),g_ram_draw_tags+offset,g_ram_draw_tags+offset+len);\"], [\"    g_pending.erase(g_pending.begin(), g_pending.begin() + used);\", \"    g_pending.erase(g_pending.begin(), g_pending.begin() + used);\\n    g_pending_tags.erase(g_pending_tags.begin(),g_pending_tags.begin()+used);\"], [\"static uint32_t cp_consume(\", \"int gx_source_draw_tag(const uint8_t* p){\\n    uintptr_t at=uintptr_t(p),base=uintptr_t(g_mem);\\n    if(at>=base && at-base<sizeof(g_ram_draw_tags))return g_ram_draw_tags[at-base];\\n    uintptr_t pending=uintptr_t(g_pending.data());\\n    if(!g_pending.empty() && at>=pending && at-pending<g_pending_tags.size())return g_pending_tags[at-pending];\\n    return -1;\\n}\\nint gx_direct_draw_tag(const uint8_t* p){return fe_threaded()?-1:gx_source_draw_tag(p);}\\nstatic uint32_t cp_consume(\"]], \"c\": [[\"namespace gx {\", \"int gx_source_draw_tag(const uint8_t*);\\nint gx_direct_draw_tag(const uint8_t*);\\nnamespace gx {\\nvoid draw_tag_reached(uint8_t);\"], [\"        const uint8_t cmd = p[0];\\n        need = 0;\", \"        const uint8_t cmd = p[0];\\n        static int lastTag=-1;\\n        int tag=gx_source_draw_tag(p);\\n        if(tag==0 && lastTag>=0)tag=lastTag;\\n        if(tag>=0 && tag!=lastTag){out.push_back(0x7f);out.push_back(uint8_t(tag));lastTag=tag;}\\n        need = 0;\"], [\"        uint8_t cmd = p[0];\\n        uint32_t need;\", \"        uint8_t cmd = p[0];\\n        int tag=gx_direct_draw_tag(p);\\n        if(tag>0)draw_tag_reached(uint8_t(tag));\\n        uint32_t need;\"], [\"        case 0x00: pos += 1; continue;           // NOP\", \"        case 0x7f: if(avail<2)goto partial; draw_tag_reached(p[1]);pos+=2;continue; // host-only metadata\\n        case 0x00: pos += 1; continue;           // NOP\"]], \"r\": [[\"extern uint8_t g_gp_buf[64];\", \"extern uint8_t g_gp_buf[64];\\nextern uint8_t g_gp_tags[64];\\nextern uint8_t g_cpu_write_tag;\"], [\"static inline int gp_store32(uint32_t a, uint32_t v) {\\n#ifndef GCN_CALL_TRACE\\n    if ((a & 0xFFFFF000u) == 0xCC008000u) {\\n        v = GCN_BSWAP32(v);\\n        memcpy(g_gp_buf + g_gp_len, &v, 4);\\n        g_gp_len += 4;\\n        if (g_gp_len >= 32) gp_flush_line();\\n        return 1;\\n    }\\n#else\\n    (void)a; (void)v;\\n#endif\\n    return 0;\\n}\", \"static inline int gp_store32(uint32_t a, uint32_t v) {\\n#ifndef GCN_CALL_TRACE\\n    if ((a & 0xFFFFF000u) == 0xCC008000u) {\\n        memset(g_gp_tags+g_gp_len,g_cpu_write_tag,4);\\n        v = GCN_BSWAP32(v);\\n        memcpy(g_gp_buf + g_gp_len, &v, 4);\\n        g_gp_len += 4;\\n        if (g_gp_len >= 32) gp_flush_line();\\n        return 1;\\n    }\\n#else\\n    (void)a; (void)v;\\n#endif\\n    return 0;\\n}\"], [\"static inline int gp_store16(uint32_t a, uint32_t v) {\\n    if ((a & 0xFFFFF000u) == 0xCC008000u) {\\n        g_gp_buf[g_gp_len] = (uint8_t)(v >> 8);\\n        g_gp_buf[g_gp_len + 1] = (uint8_t)v;\\n        g_gp_len += 2;\\n        if (g_gp_len >= 32) gp_flush_line();\\n        return 1;\\n    }\\n    return 0;\\n}\", \"static inline int gp_store16(uint32_t a, uint32_t v) {\\n    if ((a & 0xFFFFF000u) == 0xCC008000u) {\\n        memset(g_gp_tags+g_gp_len,g_cpu_write_tag,2);\\n        g_gp_buf[g_gp_len] = (uint8_t)(v >> 8);\\n        g_gp_buf[g_gp_len + 1] = (uint8_t)v;\\n        g_gp_len += 2;\\n        if (g_gp_len >= 32) gp_flush_line();\\n        return 1;\\n    }\\n    return 0;\\n}\"], [\"static inline int gp_store8(uint32_t a, uint32_t v) {\\n    if ((a & 0xFFFFF000u) == 0xCC008000u) {\\n        g_gp_buf[g_gp_len++] = (uint8_t)v;\\n        if (g_gp_len >= 32) gp_flush_line();\\n        return 1;\\n    }\\n    return 0;\\n}\", \"static inline int gp_store8(uint32_t a, uint32_t v) {\\n    if ((a & 0xFFFFF000u) == 0xCC008000u) {\\n        memset(g_gp_tags+g_gp_len,g_cpu_write_tag,1);\\n        g_gp_buf[g_gp_len++] = (uint8_t)v;\\n        if (g_gp_len >= 32) gp_flush_line();\\n        return 1;\\n    }\\n    return 0;\\n}\"]]}")
for name,key in [("fifo.cpp","f"),("cmd.cpp","c"),("recomp.h","r")]:
 p=root/("runtime" if name=="recomp.h" else "runtime/gx")/name
 s=p.read_text()
 if "FZGX_RECORDED_DRAW_TAGS" in s:continue
 for old,new in ops[key]:
  if s.count(old)!=1:raise SystemExit("Pinned recorded-tag anchor changed: "+name+":"+old[:60])
  s=s.replace(old,new)
 p.write_text("// FZGX_RECORDED_DRAW_TAGS\n"+s)
print("Recorded FIFO and display-list draw metadata enabled")

